target.css:
:root {
  --ink: #24362d;
  --muted: #66776d;
  --paper: #fffdf6;
  --line: #d9e0ce;
  --apple: #c94e3f;
  --leaf: #577a46;
  --cream: #f1f3df;
  --gold: #e7b94e;
}

.cider-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.card-header section,
.pickup-details {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.card-header h2 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--cream);
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.pickup-body {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 14px;
  padding: 14px 18px;
}

.crate-mark {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0;
  border: 1px solid var(--gold);
  border-radius: 12px;
  background: var(--cream);
}

.crate-mark span {
  font-size: 29px;
  line-height: 1;
}

.crate-mark figcaption {
  margin-top: 5px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 700;
}

.pickup-time {
  margin: 2px 0 4px;
  font-size: 15px;
  font-weight: 750;
}

.location {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.facts {
  display: flex;
  gap: 18px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.facts li {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.facts strong {
  color: var(--apple);
  font-size: 14px;
}

.facts span {
  color: var(--muted);
  font-size: 11px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  border-top: 1px solid var(--line);
  background: var(--cream);
}

.card-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.card-footer button {
  border: 0;
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--apple);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

